'use client';

import { useState } from 'react';
import { useLoads, useUpdateLoad } from '@/hooks/use-loads';
import { useDrivers, useVehicles } from '@/hooks';
import { StatusBadge } from '@/components/status-badge';
import { Button } from '@/components/ui/button';
import { Skeleton } from '@/components/ui/skeleton';
import { Separator } from '@/components/ui/separator';
import { toast } from 'sonner';
import { Truck, User, Package, RefreshCw } from 'lucide-react';
import type { Driver, Vehicle, Load } from '@/types';

interface DispatchCardProps {
  load: Load;
  drivers: Driver[];
  vehicles: Vehicle[];
}

function DispatchCard({ load, drivers, vehicles }: DispatchCardProps) {
  const { mutate: updateLoad, isPending } = useUpdateLoad(load.id);
  const [selectedDriver, setSelectedDriver] = useState('');
  const [selectedVehicle, setSelectedVehicle] = useState('');

  const handleDispatch = () => {
    updateLoad(
      { status: 'ASSIGNED' },
      {
        onSuccess: () => toast.success(`Load ${load.referenceNumber} dispatched!`),
        onError: () => toast.error('Dispatch failed'),
      }
    );
  };

  const statusColor = {
    PENDING: 'border-l-amber-400',
    ASSIGNED: 'border-l-blue-500',
    IN_TRANSIT: 'border-l-violet-500',
    DELIVERED: 'border-l-emerald-500',
    CANCELLED: 'border-l-red-400',
  }[load.status] ?? 'border-l-gray-200';

  return (
    <div className={`rounded-xl border border-l-4 ${statusColor} bg-white dark:bg-gray-950 p-4 shadow-sm space-y-3 hover:shadow-md transition-shadow`}>
      <div className="flex items-start justify-between">
        <div>
          <p className="font-mono font-bold text-blue-600 dark:text-blue-400">{load.referenceNumber}</p>
          <p className="text-xs text-muted-foreground mt-0.5">
            {load.originCity} → {load.destinationCity}
          </p>
        </div>
        <StatusBadge status={load.status} />
      </div>

      <div className="text-xs flex items-center justify-between">
        <span className="text-muted-foreground">Rate</span>
        <span className="font-semibold">${load.rate.toLocaleString('en-US', { minimumFractionDigits: 2 })}</span>
      </div>

      <Separator />

      <div className="space-y-2">
        <select
          className="w-full h-8 text-xs rounded-md border border-input bg-background px-2 py-1 disabled:opacity-50 disabled:cursor-not-allowed"
          value={selectedDriver}
          onChange={(e) => setSelectedDriver(e.target.value)}
          disabled={load.status !== 'PENDING'}
        >
          <option value="">Assign Driver…</option>
          {drivers.filter(d => d.status === 'AVAILABLE').map((d) => (
            <option key={d.id} value={d.id}>{d.firstName} {d.lastName}</option>
          ))}
        </select>

        <select
          className="w-full h-8 text-xs rounded-md border border-input bg-background px-2 py-1 disabled:opacity-50 disabled:cursor-not-allowed"
          value={selectedVehicle}
          onChange={(e) => setSelectedVehicle(e.target.value)}
          disabled={load.status !== 'PENDING'}
        >
          <option value="">Assign Vehicle…</option>
          {vehicles.filter(v => v.status === 'IN_SERVICE').map((v) => (
            <option key={v.id} value={v.id}>{v.licensePlate} — {v.make} {v.model}</option>
          ))}
        </select>
      </div>

      {load.status === 'PENDING' && (
        <Button
          size="sm"
          className="w-full bg-blue-600 hover:bg-blue-700 h-8 text-xs gap-1"
          onClick={handleDispatch}
          disabled={isPending}
        >
          <Truck className="h-3 w-3" />
          {isPending ? 'Dispatching…' : 'Dispatch'}
        </Button>
      )}
    </div>
  );
}

export default function DispatchPage() {
  const { data: loadsData, isLoading: loadsLoading, refetch } = useLoads({ limit: 100 });
  const { data: driversData } = useDrivers({ limit: 200 });
  const { data: vehiclesData } = useVehicles({ limit: 200 });

  const loads = loadsData?.data ?? [];
  const drivers = driversData?.data ?? [];
  const vehicles = vehiclesData?.data ?? [];

  const columns = [
    { status: 'PENDING', label: 'Pending', color: 'bg-amber-50 dark:bg-amber-900/10 border-amber-100 dark:border-amber-800' },
    { status: 'ASSIGNED', label: 'Assigned', color: 'bg-blue-50 dark:bg-blue-900/10 border-blue-100 dark:border-blue-800' },
    { status: 'IN_TRANSIT', label: 'In Transit', color: 'bg-violet-50 dark:bg-violet-900/10 border-violet-100 dark:border-violet-800' },
    { status: 'DELIVERED', label: 'Delivered', color: 'bg-emerald-50 dark:bg-emerald-900/10 border-emerald-100 dark:border-emerald-800' },
  ];

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Dispatch Board</h1>
          <p className="text-muted-foreground mt-1">
            {drivers.filter(d => d.status === 'AVAILABLE').length} drivers available •{' '}
            {vehicles.filter(v => v.status === 'IN_SERVICE').length} vehicles in service
          </p>
        </div>
        <Button variant="outline" size="sm" onClick={() => refetch()} className="gap-2">
          <RefreshCw className="h-4 w-4" />
          Refresh
        </Button>
      </div>

      {/* Stats bar */}
      <div className="grid grid-cols-4 gap-3">
        {columns.map((col) => {
          const count = loads.filter(l => l.status === col.status).length;
          return (
            <div key={col.status} className={`rounded-lg border p-3 ${col.color}`}>
              <p className="text-xs text-muted-foreground">{col.label}</p>
              <p className="text-2xl font-bold mt-0.5">{count}</p>
            </div>
          );
        })}
      </div>

      {/* Kanban Board */}
      {loadsLoading ? (
        <div className="grid grid-cols-4 gap-4">
          {columns.map((col) => (
            <div key={col.status} className="space-y-3">
              <Skeleton className="h-6 w-24" />
              {Array.from({ length: 3 }).map((_, i) => <Skeleton key={i} className="h-48 w-full rounded-xl" />)}
            </div>
          ))}
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 flex-1 overflow-auto">
          {columns.map((col) => {
            const colLoads = loads.filter(l => l.status === col.status);
            return (
              <div key={col.status} className="space-y-3">
                <div className="flex items-center justify-between">
                  <h3 className="font-semibold text-sm">{col.label}</h3>
                  <span className="text-xs text-muted-foreground bg-gray-100 dark:bg-gray-800 px-2 py-0.5 rounded-full">
                    {colLoads.length}
                  </span>
                </div>
                {colLoads.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-10 border-2 border-dashed rounded-xl text-center">
                    <Package className="h-6 w-6 text-gray-300 dark:text-gray-600 mb-2" />
                    <p className="text-xs text-muted-foreground">No loads</p>
                  </div>
                ) : (
                  <div className="space-y-3">
                    {colLoads.map((load) => (
                      <DispatchCard
                        key={load.id}
                        load={load}
                        drivers={drivers}
                        vehicles={vehicles}
                      />
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

