          </Link>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-2xl font-bold tracking-tight font-mono text-blue-600 dark:text-blue-400">
                {trip.tripNumber}
              </h1>
              <StatusBadge status={trip.status} />
            </div>
            <p className="text-sm text-muted-foreground mt-0.5">
              Created {format(new Date(trip.createdAt), 'MMM d, yyyy')}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {allowedTransitions.length > 0 && (
          <select
            className="w-44 h-9 rounded-md border border-input bg-background px-3 py-2 text-sm"
            onChange={(e) => e.target.value && handleStatusChange(e.target.value)}
            defaultValue=""
            disabled={isPending}
          >
            <option value="" disabled>Change Status</option>
            {allowedTransitions.map((s) => (
              <option key={s} value={s}>{s.replace('_', ' ')}</option>
            ))}
          </select>
          )}
          <Button variant="outline" size="sm">Edit Trip</Button>
        </div>
