                    { label: 'End Date', value: trip.endDate ? format(new Date(trip.endDate), 'MMM d, yyyy') : '—' },
                    { label: 'ETA', value: trip.eta ? format(new Date(trip.eta), 'MMM d, h:mm a') : '—' },
                    { label: 'Est. Distance', value: trip.estimatedDistance ? `${trip.estimatedDistance.toLocaleString()} mi` : '—' },
                    { label: 'Actual Distance', value: trip.actualDistance ? `${trip.actualDistance.toLocaleString()} mi` : '—' },
                  ].map((item) => (
                    <div key={item.label}>
                      <dt className="text-xs text-muted-foreground">{item.label}</dt>
                      <dd className="text-sm font-medium mt-0.5">{item.value}</dd>
                    </div>
                  ))}
                </dl>
                {trip.notes && (
