              </div>

              {/* Driver & Vehicle */}
              <div className="grid grid-cols-2 gap-4">
                <div className="rounded-xl border bg-white dark:bg-gray-950 p-5 shadow-sm">
                  <h3 className="font-semibold mb-3 flex items-center gap-2">
                    <User className="h-4 w-4 text-blue-500" /> Driver
                  </h3>
                  {trip.driver ? (
                    <div>
                      <div className="h-10 w-10 rounded-full bg-blue-100 dark:bg-blue-900 flex items-center justify-center text-blue-700 dark:text-blue-300 font-semibold mb-2">
                        {trip.driver.firstName[0]}{trip.driver.lastName[0]}
                      </div>
                      <p className="font-medium">{trip.driver.firstName} {trip.driver.lastName}</p>
                      <p className="text-xs text-muted-foreground">{trip.driver.phone}</p>
                      <StatusBadge status={trip.driver.status} className="mt-2" />
                    </div>
                  ) : (
                    <div className="text-center py-4">
                      <p className="text-sm text-muted-foreground">No driver assigned</p>
                      <Button variant="outline" size="sm" className="mt-2">Assign</Button>
                    </div>
                  )}
                </div>
                <div className="rounded-xl border bg-white dark:bg-gray-950 p-5 shadow-sm">
                  <h3 className="font-semibold mb-3 flex items-center gap-2">
                    <Truck className="h-4 w-4 text-blue-500" /> Vehicle
