                  {trip.vehicle ? (
                    <div>
                      <p className="font-mono font-bold text-lg">{trip.vehicle.licensePlate}</p>
                      <p className="text-sm text-muted-foreground">{trip.vehicle.make} {trip.vehicle.model} {trip.vehicle.year}</p>
                      <StatusBadge status={trip.vehicle.status} className="mt-2" />
