              <div className="rounded-xl border bg-white dark:bg-gray-950 p-5 shadow-sm space-y-3">
                <div className="flex items-center justify-between">
                  <h3 className="font-semibold flex items-center gap-2">
                    <Package className="h-4 w-4 text-blue-500" /> Loads
                  </h3>
                  <Button size="sm" variant="outline">Add Load</Button>
                </div>
                {trip.loads && trip.loads.length > 0 ? (
                  trip.loads.map((load) => (
