                      <div className="flex items-center justify-between p-3 rounded-lg border hover:bg-gray-50 dark:hover:bg-gray-900 transition-colors">
                        <div>
                          <p className="font-mono font-medium text-blue-600">{load.referenceNumber}</p>
                          <p className="text-xs text-muted-foreground">
