                    { label: 'Fuel Expenses', value: trip.fuelExpenses ? `$${trip.fuelExpenses.toFixed(2)}` : '—' },
                    { label: 'Other Expenses', value: trip.otherExpenses ? `$${trip.otherExpenses.toFixed(2)}` : '—' },
                    {
                      label: 'Total Expenses',
                      value: `$${((trip.fuelExpenses ?? 0) + (trip.otherExpenses ?? 0)).toFixed(2)}`,
                      bold: true,
                    },
                  ].map((item) => (
                    <div key={item.label} className="flex justify-between py-2.5">
                      <dt className="text-sm text-muted-foreground">{item.label}</dt>
                      <dd className={`text-sm ${(item as any).bold ? 'font-bold' : ''}`}>{item.value}</dd>
                    </div>
