                { label: 'Trip ID', value: id.slice(0, 8) + '…' },
                { label: 'Created', value: format(new Date(trip.createdAt), 'MMM d, yyyy') },
                { label: 'Last Updated', value: format(new Date(trip.updatedAt), 'MMM d, yyyy h:mm a') },
                { label: 'Loads', value: String(trip.loads?.length ?? 0) },
              ].map((item) => (
                <div key={item.label} className="flex justify-between">
                  <dt className="text-xs text-muted-foreground">{item.label}</dt>
                  <dd className="text-xs font-medium font-mono">{item.value}</dd>
