import { useState } from 'react';
import { ColumnDef } from '@tanstack/react-table';
import { MoreHorizontal, Plus, Map } from 'lucide-react';
import { format } from 'date-fns';
import { toast } from 'sonner';
import { useTrips } from '@/hooks';
