  },
  {
    id: 'vehicle',
    header: 'Vehicle',
    cell: ({ row }) =>
      row.original.vehicle
        ? `${row.original.vehicle.licensePlate ?? row.original.vehicle.id}`
        : <span className="text-muted-foreground">Unassigned</span>,
