        <DropdownMenuContent align="end">
          <DropdownMenuLabel>Actions</DropdownMenuLabel>
          <DropdownMenuItem>View Details</DropdownMenuItem>
          <DropdownMenuItem>Track Live</DropdownMenuItem>
          <DropdownMenuItem>Edit Trip</DropdownMenuItem>
          <DropdownMenuItem className="text-red-600">Cancel Trip</DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    ),
  },
];

export default function TripsPage() {
  const { data, isLoading, isError } = useTrips({ page: 1, limit: 50 });

  if (isError) {
    return (
      <div className="flex flex-col items-center justify-center h-64 gap-4">
        <Map className="h-12 w-12 text-red-400" />
        <p className="text-lg font-medium">Failed to load trips</p>
        <p className="text-sm text-muted-foreground">Check your API connection and try again.</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Trips</h1>
          <p className="text-muted-foreground mt-1">
            {data ? `${data.total.toLocaleString()} total trips` : 'Loading...'}
          </p>
        </div>
        <Button className="bg-blue-600 hover:bg-blue-700 gap-2">
          <Plus className="h-4 w-4" />
          Plan Trip
        </Button>
      </div>

      {isLoading ? (
        <div className="space-y-3">
          {Array.from({ length: 8 }).map((_, i) => (
            <Skeleton key={i} className="h-12 w-full rounded-md" />
          ))}
        </div>
      ) : (
        <DataTable columns={columns} data={data?.data ?? []} searchKey="tripNumber" />
      )}
    </div>
  );
}

